import React from 'react';

export default function Projects() {
const projects = [
{ name: 'MindBridge - AI Mental Health Chatbot', desc: 'A chatbot for student emotional support.' },
{ name: 'Healthcare Predictor', desc: 'Predicts patient health outcomes using past data.' },
{ name: 'NGO Impact Dashboard', desc: 'Tracks and visualizes project performance.' }
];

return (
<div style={{ padding: '40px' }}>
<h2>My Projects</h2>
<ul>
{projects.map((p, i) => (
<li key={i} style={{ marginBottom: '10px' }}>
<strong>{p.name}</strong> - {p.desc}
</li>
))}
</ul>
</div>
);
}
